mapper.select:
SELECT
kb.knowledge_id AS knowledgeId,
kb.knowledge_name,
COUNT(rel.kb_id) AS refCount
FROM bt_knowledge_base kb
LEFT JOIN bt_dc_qa_record_kb_rel rel ON rel.kb_id = kb.knowledge_id AND rel.status_cd = '00A' AND rel.tenant_id = #{query.tenantId}
LEFT JOIN bt_dc_qa_record qa ON qa.qa_id = rel.qa_id AND qa.status_cd = '00A' AND qa.tenant_id = #{query.tenantId}
WHERE kb.status_cd = '00A'
AND kb.tenant_id = #{query.tenantId}

  AND kb.knowledge_name LIKE

  #{query.searchContent}


GROUP BY kb.knowledge_id, kb.knowledge_name
ORDER BY refCount DESC, MAX(kb.created_time) DESC

SELECT
bd.ext_system_id AS docId,
bd.doc_name AS documentName,
kb.knowledge_name AS knowledgeName,
COUNT(DISTINCT ref.qa_id) AS refCount
FROM bt_document bd
LEFT JOIN bt_knowledge_base kb ON kb.knowledge_id = bd.knowledge_id  AND kb.tenant_id = #{query.tenantId}
LEFT JOIN bt_dc_qa_chunk_reference ref ON ref.doc_id = bd.ext_system_id AND ref.status_cd = '00A' AND ref.tenant_id = #{query.tenantId}
LEFT JOIN bt_dc_qa_record qa ON qa.qa_id = ref.qa_id AND qa.status_cd = '00A' AND qa.tenant_id = #{query.tenantId}
WHERE bd.status_cd = '00A'
AND kb.status_cd = '00A'
AND bd.tenant_id = #{query.tenantId}

  AND bd.doc_name LIKE

  #{query.searchContent}


GROUP BY bd.ext_system_id, bd.doc_name, kb.knowledge_name
ORDER BY refCount DESC, MAX(bd.created_time) DESC

SELECT
qa.question,
COUNT(*) AS count
FROM bt_dc_qa_record qa
WHERE qa.status_cd = '00A'
AND qa.tenant_id = #{query.tenantId}

  AND qa.created_time >= #{query.startTime}


  AND qa.created_time <= #{query.endTime}

GROUP BY qa.question
ORDER BY count DESC

SELECT
CAST(qa.question AS VARCHAR2(4000)) AS question,
COUNT(*) AS count
FROM bt_dc_qa_record qa
WHERE qa.status_cd = '00A'
AND qa.tenant_id = #{query.tenantId}

  AND qa.created_time >= #{query.startTime}


  AND qa.created_time <= #{query.endTime}

GROUP BY CAST(qa.question AS VARCHAR2(4000))
ORDER BY count DESC

SELECT qa.standard_question AS question, COUNT(*) AS count FROM bt_dc_qa_record qa WHERE qa.status_cd = '00A' AND qa.tenant_id = #{query.tenantId} AND qa.standard_question IS NOT NULL AND qa.standard_question != ''
AND qa.created_time >= #{query.startTime}
AND qa.created_time <= #{query.endTime}
GROUP BY qa.standard_question ORDER BY COUNT(*) DESC

SELECT CAST(qa.standard_question AS VARCHAR2(4000)) AS question, COUNT(*) AS count FROM bt_dc_qa_record qa WHERE qa.status_cd = '00A' AND qa.tenant_id = #{query.tenantId} AND qa.standard_question IS NOT NULL
AND qa.created_time >= #{query.startTime}
AND qa.created_time <= #{query.endTime}
GROUP BY CAST(qa.standard_question AS VARCHAR2(4000)) ORDER BY COUNT(*) DESC

SELECT qa.feedback_type
FROM bt_dc_qa_record qa
WHERE qa.status_cd = '00A'
  AND qa.user_feedback = 'DISLIKE'
  AND qa.feedback_type IS NOT NULL
  AND qa.tenant_id = #{query.tenantId}

  AND qa.created_time >= #{query.startTime}


  AND qa.created_time <= #{query.endTime}

SELECT
SUM(CASE WHEN a.user_feedback = 'LIKE'    THEN 1 ELSE 0 END) AS likeCount,
SUM(CASE WHEN a.user_feedback = 'DISLIKE' THEN 1 ELSE 0 END) AS dislikeCount
FROM bt_dc_qa_record a
WHERE a.status_cd = '00A'
AND a.tenant_id = #{query.tenantId}

  AND a.created_time >= #{query.startTime}


  AND a.created_time <= #{query.endTime}

SELECT
u.user_id AS userId,
u.real_name,
COUNT(bd.document_id) AS uploadCount
FROM bt_tenant_user tu
LEFT JOIN bt_user u ON u.user_id = tu.user_id
LEFT JOIN bt_dc_document_contributor c ON c.user_id = u.user_id AND c.status_cd = '00A' AND c.tenant_id = #{query.tenantId}
LEFT JOIN bt_document bd ON bd.dc_document_id = c.document_id AND bd.status_cd = '00A' AND bd.tenant_id = #{query.tenantId}
WHERE tu.tenant_id = #{query.tenantId}
AND tu.status_cd = '00A'
AND u.status_cd = '00A'

  AND u.real_name LIKE

  #{query.searchContent}



  AND c.created_time >= #{query.startTime}


  AND c.created_time <= #{query.endTime}

GROUP BY u.user_id, u.real_name
ORDER BY uploadCount DESC, MAX(u.created_time) ASC

SELECT AS name, COUNT(*) AS value FROM ( SELECT bd.created_time AS created_time FROM bt_dc_document_contributor c LEFT JOIN bt_document bd ON bd.dc_document_id = c.document_id LEFT JOIN bt_user u ON u.user_id = c.user_id LEFT JOIN bt_tenant_user tu ON tu.user_id = u.user_id AND tu.tenant_id = c.tenant_id WHERE c.status_cd = '00A' AND bd.status_cd = '00A' AND u.status_cd = '00A' AND tu.status_cd = '00A' AND c.tenant_id = #{query.tenantId}
AND bd.created_time >= #{query.startTime}
AND bd.created_time <= #{query.endTime}
) t GROUP BY ORDER BY name ASC

SELECT
u.user_id AS userId,
u.real_name,
COUNT(qa.qa_id) AS questionCount
FROM bt_tenant_user tu
LEFT JOIN bt_user u ON u.user_id = tu.user_id
LEFT JOIN bt_dc_qa_record qa ON qa.creator_id = u.user_id AND qa.status_cd = '00A' AND qa.tenant_id = #{query.tenantId}
WHERE tu.tenant_id = #{query.tenantId}
AND tu.status_cd = '00A'
AND u.status_cd = '00A'

  AND u.real_name LIKE

  #{query.searchContent}



  AND qa.created_time >= #{query.startTime}


  AND qa.created_time <= #{query.endTime}

GROUP BY u.user_id, u.real_name
ORDER BY questionCount DESC, MAX(u.created_time) ASC

SELECT AS name, COUNT(*) AS value FROM ( SELECT qa.created_time AS created_time FROM bt_dc_qa_record qa LEFT JOIN bt_user u ON u.user_id = qa.creator_id LEFT JOIN bt_tenant_user tu ON tu.user_id = u.user_id AND tu.tenant_id = qa.tenant_id WHERE qa.status_cd = '00A' AND tu.status_cd = '00A' AND u.status_cd = '00A' AND qa.tenant_id = #{query.tenantId}
AND qa.created_time >= #{query.startTime}
AND qa.created_time <= #{query.endTime}
) t GROUP BY ORDER BY name ASC

SELECT a.qa_id, a.question, a.answer, a.created_time, u.real_name AS creatorName, a.feedback_type, a.feedback_reason, a.operate_state, k.knowledge_name FROM bt_dc_qa_record a LEFT JOIN bt_dc_qa_record_kb_rel b ON b.qa_id = a.qa_id LEFT JOIN bt_knowledge_base k ON k.knowledge_id = b.kb_id AND k.tenant_id = #{query.tenantId} LEFT JOIN bt_user u ON u.user_id = a.creator_id WHERE a.status_cd = '00A' AND a.user_feedback = 'DISLIKE' AND a.tenant_id = #{query.tenantId}
AND (
(a.feedback_type = #{type} OR a.feedback_type LIKE CONCAT(#{type}, ',%') OR a.feedback_type LIKE CONCAT('%,', #{type}, ',%') OR a.feedback_type LIKE CONCAT('%,', #{type}))
)
AND u.real_name LIKE
#{query.searchContent}
ORDER BY a.created_time DESC
